    expect((err as ModelError).message).toContain('<redacted>')
    expect((err as ModelError).message).not.toContain(DUMMY_KEY)
  })

  it.each([
    ['an error object on 200', () => ({ body: { error: { message: `key ${DUMMY_KEY} rejected` } } })],
    ['a non-JSON body', () => ({ body: `forbidden: ${DUMMY_KEY}` })],
    ['a 200 without choices', () => ({ body: { id: 'c1' } })],
  ])('masks the key in %s', async (_label, turn) => {
    fake = await startFakeModelServer([turn()])
    const client = createModelClient({ baseUrl: fake.baseUrl, name: 'm', apiKey: DUMMY_KEY })
    const err = await client.complete([{ role: 'user', content: 'x' }], {}).catch((e) => e)
    expect(err instanceof ModelError).toBe(true)
    expect((err as ModelError).message).toContain('<redacted>')
    expect((err as ModelError).message).not.toContain(DUMMY_KEY)
  })

  it('leaves no 6+ char fragment of the key when the body places it across the 200-char cut', async () => {
    // 190 chars before the key: without the mask the cut would keep the first 10 chars of the key.
    const message = 'x'.repeat(190) + DUMMY_KEY
    fake = await startFakeModelServer([{ status: 401, body: { error: { message } } }])
    const client = createModelClient({ baseUrl: fake.baseUrl, name: 'm', apiKey: DUMMY_KEY })
    const err = await client.complete([{ role: 'user', content: 'x' }], {}).catch((e) => e)
    expect(err instanceof ModelError).toBe(true)
    const msg = (err as ModelError).message
    expect(msg).toContain('<redacted>')
    expect(msg).not.toContain(DUMMY_KEY)
    // Review Focus 1: no 6-char substring of the key survives the cut.
    for (let i = 0; i + 6 <= DUMMY_KEY.length; i++) expect(msg, DUMMY_KEY.slice(i, i + 6)).not.toContain(DUMMY_KEY.slice(i, i + 6))
  })

  it('keeps the usage honest when the body has no usage block', async () => {
    fake = await startFakeModelServer([{ body: { choices: [{ message: { role: 'assistant', content: 'x' } }] } }])"}

