    const { trace, requests } = await run([{ body: completion({ content: 'x' }) }], (b) => ({ model: { baseUrl: b, name: 'm', apiKey: 'sk-test-secret' } }))
    expect(requests[0].headers.authorization).toBe('Bearer sk-test-secret')
    expect(dirContains(trace.dir, 'sk-test-secret')).toBe(false)
  })","new_string":"  it('keeps the apiKey out of every file in the run dir', async () => {
    const { trace, requests } = await run([{ body: completion({ content: 'x' }) }], (b) => ({ model: { baseUrl: b, name: 'm', apiKey: 'sk-test-secret' } }))
    expect(requests[0].headers.authorization).toBe('Bearer sk-test-secret')
    expect(dirContains(trace.dir, 'sk-test-secret')).toBe(false)
  })

  it('masks the key echoed by an error body before the 200-char cut', async () => {
    const key = 'dummykeyabcdefghijklmnopqrstuvwxyz456789'
    const { result, trace } = await run([{ status: 401, body: { error: { message: 'x'.repeat(190) + key } } }], (b) => ({ model: { baseUrl: b, name: 'm', apiKey: key } }))
    expect(result.status).toBe('failed')
    expect(result.error?.code).toBe('MODEL_ERROR')
    expect(result.error?.message).toContain('<redacted>')
    expect(result.error?.message).not.toContain(key)
    // review focus 1: no 6-char part of the key survives the cut
    for (let i = 0; i + 6 <= key.length; i++) expect(result.error?.message, key.slice(i, i + 6)).not.toContain(key.slice(i, i + 6))
    const runEnd = readTrace(trace.dir).find((e) => e.type === 'run_end')
    expect(runEnd).toMatchObject({ type: 'run_end', status: 'failed', error: { code: 'MODEL_ERROR' } })
    expect(JSON.stringify(runEnd)).not.toContain(key)
    expect(dirContains(trace.dir, key)).toBe(false)
  })"}

